create table if not exists ambientes(id serial primary key,slug text unique not null,nome text not null,imagem text,ordem int default 0,ativo boolean default true);
create table if not exists produtos(id serial primary key,slug text unique not null,nome text not null,descricao text,preco numeric(10,2),loja text,link_afiliado text not null,imagem text,
 ambiente_id int references ambientes(id) on delete set null,ativo boolean default true,destaque boolean default false,created_at timestamptz default now());
create table if not exists receitas(id serial primary key,slug text unique not null,nome text not null,descricao text,tempo_preparo text,rendimento text,categoria text,imagem text,
 fotos text[] default '{}',ingredientes jsonb default '[]',etapas jsonb default '[]',ativo boolean default true,destaque boolean default false,created_at timestamptz default now());
create index if not exists produtos_amb on produtos(ambiente_id) where ativo;
insert into ambientes(slug,nome,ordem) values('sala','Sala',1),('cozinha','Cozinha',2),('quarto','Quarto',3),('banheiro','Banheiro',4),('lavanderia','Lavanderia',5),('escritorio','Escritório',6),('area-externa','Área externa',7),('outros','Outros',8) on conflict do nothing;
insert into produtos(slug,nome,descricao,loja,link_afiliado,ambiente_id,destaque) select 'ducha-eletronica-zagonel-ducali-6800w','Ducha Eletrônica Zagonel Ducali 6800W 220V Black','Ducha eletrônica 6800W, 220V, preta.','Amazon','https://www.amazon.com.br/Ducha-Eletr%C3%B4nica-Zagonel-Ducali-6800W/dp/B0C6B5DGJV',id,true from ambientes where slug='banheiro' on conflict do nothing;
insert into receitas(slug,nome,descricao,tempo_preparo,rendimento,categoria,ingredientes,etapas,destaque) values('bolo-de-cenoura-exemplo','Bolo de cenoura (exemplo)','Receita de exemplo para testar o layout. Edite ou apague no painel.','50 min','12 fatias','Bolos','[{"qtd":"3","item":"cenouras médias"},{"qtd":"4","item":"ovos"},{"qtd":"1 xícara","item":"óleo"},{"qtd":"2 xícaras","item":"açúcar"},{"qtd":"2 xícaras","item":"farinha de trigo"},{"qtd":"1 colher (sopa)","item":"fermento"}]','["Bata no liquidificador a cenoura, os ovos e o óleo.","Misture com o açúcar e a farinha; acrescente o fermento por último.","Asse em forma untada a 180 °C por cerca de 40 minutos."]',true) on conflict do nothing;
